import{_ as a,H as i,f as t,i as o}from"./chunks/framework.CBmkDW73.js";const _=JSON.parse('{"title":"品質標準プロトコル (Quality Standard)","description":"","frontmatter":{},"headers":[],"relativePath":"ja/skills/quality.md","filePath":"ja/skills/quality.md"}'),n={name:"ja/skills/quality.md"};function l(c,e,d,r,s,h){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="品質標準プロトコル-quality-standard" tabindex="-1">品質標準プロトコル (Quality Standard) <a class="header-anchor" href="#品質標準プロトコル-quality-standard" aria-label="Permalink to &quot;品質標準プロトコル (Quality Standard)&quot;">​</a></h1><p>品質標準 (<code>skills/references/quality.md</code>) は、<code>tdd</code>、<code>review</code>、<code>ship</code>、<code>archive</code>、<code>onboard</code> で強制適用される品質基準を定義しています。</p><h2 id="_3次元品質検証" tabindex="-1">3次元品質検証 <a class="header-anchor" href="#_3次元品質検証" aria-label="Permalink to &quot;3次元品質検証&quot;">​</a></h2><p>実装およびリファクタリングサイクルごとに、以下の4つの観点から検証を行います。</p><h3 id="_1-メカニカルチェック-mechanical-checks" tabindex="-1">1. メカニカルチェック (Mechanical Checks) <a class="header-anchor" href="#_1-メカニカルチェック-mechanical-checks" aria-label="Permalink to &quot;1. メカニカルチェック (Mechanical Checks)&quot;">​</a></h3><ul><li>Lint ルールが警告なしで完全にパスすること。</li><li>コードフォーマットがプロジェクト設定に準拠していること。</li><li><code>any</code> による回避や型エラー抑制なしで型チェック（Typecheck）がパスすること。</li></ul><h3 id="_2-規約の遵守-convention-adherence" tabindex="-1">2. 規約の遵守 (Convention Adherence) <a class="header-anchor" href="#_2-規約の遵守-convention-adherence" aria-label="Permalink to &quot;2. 規約の遵守 (Convention Adherence)&quot;">​</a></h3><ul><li>仕様書（<code>convention:</code>）で宣言されたプロジェクト固有の慣習およびスタックのベストプラクティスを遵守していること。</li><li>イディオマティックな構造、エラー処理パターン、命名規約を評価します。</li></ul><h3 id="_3-設計評価-design-assessment" tabindex="-1">3. 設計評価 (Design Assessment) <a class="header-anchor" href="#_3-設計評価-design-assessment" aria-label="Permalink to &quot;3. 設計評価 (Design Assessment)&quot;">​</a></h3><ul><li><strong>高凝集・低結合</strong>: 関数やクラスが高凝集であり、モジュール間の結合が最小限であること。</li><li><strong>適切な抽象化レベル</strong>: 早すぎたり不必要な抽象化を回避し、契約を満たす最小限の実装にとどめること。</li></ul><h3 id="_4-ドキュメントカバレッジ-documentation-coverage" tabindex="-1">4. ドキュメントカバレッジ (Documentation Coverage) <a class="header-anchor" href="#_4-ドキュメントカバレッジ-documentation-coverage" aria-label="Permalink to &quot;4. ドキュメントカバレッジ (Documentation Coverage)&quot;">​</a></h3><ul><li>すべての公開関数、API エンドポイント、エクスポートインターフェース、環境変数、障害モードが正確に記録されていること。</li><li><code>README.md</code> のコマンドや例が実行可能かつ最新であること。</li><li>ドキュメント更新を伴わないコード変更は Code Review で不合格となります。</li></ul>',12)])])}const m=a(n,[["render",l]]);export{_ as __pageData,m as default};
